function empty(featuredOnly=false){return `<div class="project-placeholders">${uniqueProjectCards(APPROVED_PROJECT_CARDS).filter(p=>!featuredOnly||FEATURED_PROJECT_KEYS.includes(p.key)).sort((a,b)=>{const order=featuredOnly?FEATURED_PROJECT_KEYS:PROJECT_COLLECTION_ORDER;return order.indexOf(a.key)-order.indexOf(b.key)}).filter(p=>{const q=new URLSearchParams(location.hash.split("?")[1]||"").get("q")||"";const normalize=s=>s.toLowerCase().replaceAll("ı","i").normalize("NFKD").replace(/[\u0300-\u036f]/g,"");return !q||normalize(p.title+" "+p.location).includes(normalize(q))}).map(p=>`<a class="approved-project-card" data-project-key="${esc(p.key)}" href="project-review/${esc(p.key)}/" aria-label="${esc(p.title)}"><div class="project-cover"><img src="${esc(p.cover)}" alt="${esc(p.alt)}" loading="lazy" decoding="async"><span class="project-brand">Kayesta Properties</span></div><div class="approved-project-caption"><span class="project-location"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2a7 7 0 0 0-7 7c0 5 7 13 7 13s7-8 7-13a7 7 0 0 0-7-7zm0 10a3 3 0 1 1 0-6 3 3 0 0 1 0 6z"/></svg>${esc(p.location)}</span><h3>${esc(p.title)}</h3><p class="project-price-note">${lang==='en'?'Contact for price':'Fiyat için iletişime geçin'}</p><span class="project-view-button">${lang==='en'?'View project':'Projeyi incele'} ↗</span></div></a>`).join('')}</div>`}
function filters(){return `<div class="filters">${(lang==='en'?['All projects','Citizenship','Residency','Family homes','Investment']:['Tüm projeler','Vatandaşlık','İkamet','Aile evleri','Yatırım']).map((x,i)=>`<button class="chip ${i===0?'active':''}" aria-pressed="${i===0}" data-filter="${i}">${x}</button>`).join('')}</div>`}
function band(){return `<section class="question-section" id="ask"><div class="wrap"><div class="question-card"><div><div class="eyebrow">${lang==='en'?'LET’S TALK':'BİRLİKTE KONUŞALIM'}</div><h2>${lang==='en'?'Still have a question?':'Aklınızda bir soru mu var?'}</h2><p class="subtitle">${lang==='en'?'Tell us your budget, buying goal or the point you want to clarify. Start on WhatsApp or prepare a consultation request.':'Bütçenizi, satın alma amacınızı veya netleştirmek istediğiniz konuyu paylaşın. WhatsApp’tan başlayın ya da danışmanlık talebinizi hazırlayın.'}</p></div><div class="question-actions"><a class="button whatsapp-button" href="https://wa.me/905325529279" target="_blank" rel="noopener noreferrer">${lang==='en'?'Ask on WhatsApp':'WhatsApp’tan sorun'} ↗</a><a class="button" href="#consultation">${lang==='en'?'Plan a consultation':'Danışmanlık planlayın'} →</a></div></div></div></section>`}
const guides=[{id:'buying-costs',en:'What belongs in your full buying budget?',tr:'Toplam satın alma bütçesinde neler olmalı?',bodyEn:'Compare the purchase price with a separate budget for transaction charges, professional services, moving and ongoing ownership. Ask for a written, itemised estimate for your specific transaction before committing.',bodyTr:'Satın alma bedelinin yanında işlem giderleri, profesyonel hizmetler, taşınma ve devam eden mülkiyet giderleri için ayrı bütçe oluşturun. Karar vermeden önce kendi işleminize özel, kalem kalem yazılı gider dökümü isteyin.',listEn:['Purchase price and payment currency','Transaction and professional service estimates','Building dues, utilities and maintenance','Exchange-rate assumptions and payment dates'],listTr:['Satış bedeli ve ödeme para birimi','İşlem ve profesyonel hizmet gider tahminleri','Aidat, hizmet ve bakım giderleri','Döviz varsayımları ve ödeme tarihleri']},{id:'viewing-checklist',en:'Your first viewing: a practical checklist',tr:'İlk proje geziniz için kontrol listesi',bodyEn:'Keep project-level marketing material separate from the exact apartment you are considering. Record the unit number and ask which images show that unit, which show a sample apartment, and which are architectural renders.',bodyTr:'Proje tanıtım materyalini, satın almayı düşündüğünüz belirli dairenin bilgilerinden ayırın. Daire numarasını kaydedin; hangi görselin gerçek daireyi, örnek daireyi veya mimari renderı gösterdiğini sorun.',listEn:['Unit, floor and orientation','Gross and net area definitions','Documented included finishes','Current condition and handover documents'],listTr:['Daire, kat ve cephe','Brüt ve net alan tanımları','Belgelenmiş teslim kapsamı','Mevcut durum ve teslim belgeleri']},{id:'remote-checklist',en:'Planning a purchase from abroad',tr:'Yurt dışından satın alma hazırlığı',bodyEn:'Start by setting out your goals, preferred location and budget. Before making a payment, obtain transaction-specific advice and confirm who handles each step, which documents are required, and how you will receive progress updates.',bodyTr:'Önce hedefinizi, tercih ettiğiniz konumu ve bütçeyi belirleyin. Ödeme yapmadan önce kendi işleminize özel danışmanlık alın; her adımı kimin yöneteceğini, gerekli belgeleri ve ilerleme bilgisinin nasıl iletileceğini netleştirin.',listEn:['Written shortlist and criteria','Independent document review','Exact unit and video viewing','Payment and handover responsibilities'],listTr:['Yazılı kısa liste ve seçim ölçütleri','Bağımsız belge incelemesi','Belirli daire ve görüntülü gezi','Ödeme ve teslim sorumlulukları']}];

const guideUpdates={"buying-costs":{"en":"Buying property in Türkiye: where to start","tr":"Türkiye’de gayrimenkul alımı: nereden başlamalı?","bodyEn":"Start with your reason for buying, a total budget and a practical shortlist. Check whether your nationality and the exact property meet the applicable acquisition conditions. Keep property purchase, residence permission and citizenship eligibility as separate questions.","bodyTr":"Satın alma amacınızı, toplam bütçenizi ve uygulanabilir kısa listenizi belirleyerek başlayın. Uyruğunuzun ve ilgili taşınmazın edinim koşullarını sağlayıp sağlamadığını kontrol edin. Mülk alımı, ikamet izni ve vatandaşlık uygunluğunu ayrı sorular olarak değerlendirin.","listEn":["Define your buying purpose, timeline and preferred neighbourhood.","Request a dated offer identifying the exact unit and payment currency.","Budget for transaction charges and professional services as well as the price.","Verify title and property documents before committing.","If considering citizenship, check the qualifying threshold, resale restriction and transaction eligibility separately."],"listTr":["Satın alma amacı, takvim ve tercih edilen semti belirleyin.","Belirli daireyi ve ödeme para birimini gösteren tarihli teklif isteyin.","Satış bedelinin yanında işlem giderleri ve profesyonel hizmetleri bütçeleyin.","Karar vermeden önce tapu ve taşınmaz belgelerini doğrulayın.","Vatandaşlık düşünüyorsanız eşik, satmama şerhi ve işlem uygunluğunu ayrıca kontrol edin."],"source":"https://www.invest.gov.tr/en/investmentguide/pages/acquiring-property-and-citizenship.aspx"},"viewing-checklist":{"en":"Title deed and documents: your review checklist","tr":"Tapu ve belgeler: inceleme kontrol listeniz","bodyEn":"A brochure and a sample apartment do not establish the legal status of the unit you are buying. Match the written offer to the exact title record and obtain transaction-specific document review before payment. Ask the title-deed office or your qualified representative which current requirements apply.","bodyTr":"Katalog veya örnek daire, satın alacağınız bağımsız bölümün hukuki durumunu doğrulamaz. Yazılı teklifi ilgili tapu kaydıyla eşleştirin ve ödeme öncesi işleme özel belge incelemesi yaptırın. Güncel koşulları tapu müdürlüğüne veya yetkin temsilcinize sorun.","listEn":["Match the owner, parcel and independent-unit details to the proposed purchase.","Review encumbrances, restrictions and the relevant title status.","Verify permits, occupancy documentation and delivery terms where applicable.","Confirm the scope and validity of any power of attorney.","Obtain a written estimate of applicable transaction charges and document costs."],"listTr":["Malik, parsel ve bağımsız bölüm ayrıntılarını satın alınacak taşınmazla eşleştirin.","Takyidat, kısıtlamalar ve ilgili tapu durumunu inceleyin.","Uygulanabildiği ölçüde ruhsat, iskan ve teslim koşullarını doğrulayın.","Vekâletnamenin kapsamını ve geçerliliğini kontrol edin.","İşlem ve belge giderleri için yazılı döküm isteyin."],"source":"https://www.yourkeyturkiye.gov.tr/en/faq"}};for(const g of guides)if(guideUpdates[g.id])Object.assign(g,guideUpdates[g.id]);guides.push(...[{"id":"price-comparison","en":"How to compare Istanbul project prices","tr":"İstanbul proje fiyatları nasıl karşılaştırılır?","bodyEn":"A headline price only becomes useful when the unit, currency, area definition and payment dates are clear. Request a dated written offer and compare like with like. Use official housing statistics as broader context, not as a valuation of a specific apartment.","bodyTr":"Bir fiyat ancak daire, para birimi, alan tanımı ve ödeme tarihleri netleştiğinde anlamlı olur. Tarihli yazılı teklif isteyin ve benzer özellikleri karşılaştırın. Resmi konut istatistiklerini belirli bir dairenin değerlemesi olarak değil, genel piyasa bağlamı olarak kullanın.","listEn":["Match exact units: floor, orientation, net area and included finishes.","Separate the cash price from the payment-plan total; list the currency and payment dates.","Include transaction costs, building dues, maintenance and likely vacancy in your budget.","Check construction progress and written delivery obligations.","Compare dated local evidence; distinguish asking prices from confirmed transactions."],"listTr":["Belirli daireleri karşılaştırın: kat, cephe, net alan ve teslim kapsamı.","Peşin bedel ile ödeme planı toplamını ayırın; para birimi ve tarihleri yazın.","İşlem giderleri, aidat, bakım ve olası boş kalmayı bütçeye dahil edin.","İnşaat ilerlemesini ve yazılı teslim yükümlülüklerini kontrol edin.","Tarihli yerel kanıtları karşılaştırın; ilan bedelleri ile doğrulanmış işlemleri ayırın."],"source":"https://tcmb.gov.tr/wps/wcm/connect/en/tcmb%2Ben/main%2Bmenu/statistics/real%2Bsector%2Bstatistics/residential%2Bproperty%2Bprice%2Bindex"}]);
const guideCardMeta={"buying-costs":{"en":["Buyer guide","From your first shortlist to budgeting and eligibility checks."],"tr":["Alıcı rehberi","İlk kısa listeden bütçe ve uygunluk kontrollerine kadar."],"icon":"home"},"viewing-checklist":{"en":["Legal guide","The title record, supporting documents and questions to ask before payment."],"tr":["Hukuki süreç","Ödeme öncesi tapu kaydı, belgeler ve sorulacak sorular."],"icon":"document"},"price-comparison":{"en":["Price comparison","Read the whole offer: exact unit, payment plan, delivery and ownership costs."],"tr":["Fiyat karşılaştırma","Teklifi bütünüyle okuyun: daire, ödeme planı, teslim ve giderler."],"icon":"chart"}};
const uiIconPaths={"home":"<path d=\"M3 11 12 3l9 8M5 10v11h14V10M9 21v-7h6v7\"/>","document":"<path d=\"M6 3h8l4 4v14H6zM14 3v5h4M9 12h6M9 16h6\"/>","chart":"<path d=\"M3 3v18h18M7 17v-4M12 17V9M17 17V5\"/>","shield":"<path d=\"M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6zM8 12l3 3 5-6\"/>","people":"<path d=\"M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3M18 7a4 4 0 0 1 0 8M22 21v-3a4 4 0 0 0-3-3\"/><circle cx=\"9\" cy=\"6\" r=\"4\"/>","video":"<rect x=\"3\" y=\"5\" width=\"13\" height=\"14\" rx=\"2\"/><path d=\"m16 10 5-3v10l-5-3\"/>","pin":"<path d=\"M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0z\"/><circle cx=\"12\" cy=\"10\" r=\"3\"/>"};
function uiIcon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${uiIconPaths[name]||uiIconPaths.document}</svg>`}
const guidePhotos={'buying-costs':'assets/guide-buyer-ai.webp','viewing-checklist':'assets/guide-legal-ai.webp','price-comparison':'assets/guide-market-ai.webp'};
function guideCards(){return `<div class="cards guide-cards">${['buying-costs','viewing-checklist','price-comparison'].map((id,i)=>{const g=guides.find(g=>g.id===id),m=guideCardMeta[id];return `<a class="card guide-card" href="#guide/${g.id}"><div class="guide-cover guide-cover-${i}"><span class="guide-badge">${m[lang][0]}</span>${guidePhotos[id]?`<img class="guide-photo" src="${guidePhotos[id]}" alt="${lang==='en'?'AI-generated thematic guide illustration':'AI ile üretilmiş tematik rehber görseli'}" loading="eager" decoding="async">`:`${uiIcon(m.icon)}<span class="guide-cover-number">0${i+1}</span>`}</div><div class="guide-card-body"><div class="guide-date">${lang==='en'?'October 2026':'Ekim 2026'}</div><h3>${g[lang]}</h3><p>${m[lang][1]}</p><span class="guide-read">${lang==='en'?'Read the guide':'Rehberi oku'} →</span></div></a>`}).join('')}</div>`}
function pageHead(title,desc=''){return `<section class="pagehead"><div class="wrap"><div class="breadcrumbs"><a href="#home">${lang==='en'?'HOME':'ANA SAYFA'}</a> / ${esc(title)}</div><h1>${esc(title)}</h1>${desc?`<p>${esc(desc)}</p>`:''}</div></section>`}
const informationData={"en":[["$400K","Citizenship threshold","The minimum property value for Türkiye’s real-estate citizenship route. A three-year restriction on resale and transaction-specific eligibility checks apply. Purchasing alone does not guarantee approval.","#citizenship","Understand the requirements","Official guide · checked 5 Oct 2026","https://www.invest.gov.tr/en/investmentguide/pages/acquiring-property-and-citizenship.aspx"],["15.75M","Istanbul population","15,754,053 residents across Istanbul province in 2025. Compare commute times, ferry and metro access, schools and daily amenities before choosing your neighbourhood.","#districts","Explore your neighbourhood fit","TurkStat · 2025 population","https://data.tuik.gov.tr/Bulten/Index?p=Adrese-Dayali-Nufus-Kayit-Sistemi-Sonuclari-2025-53899"],["Life Match","Your priorities, your neighbourhood","Waterfront walks, green surroundings, family routines or a shorter commute: start with how you want to live. Shape a focused neighbourhood shortlist around your budget and priorities.","#districts","Find your Istanbul"],["Every step","Guidance through the journey","From your first questions to viewings, document checks and title-deed planning, clarify each next step and who handles it. Agree the service scope and any specialist support before you commit.","#guide/remote-checklist","Plan your buying journey"]],"tr":[["$400K","Vatandaşlık eşiği","Gayrimenkul yoluyla vatandaşlık başvurusu için asgari taşınmaz değeri. Üç yıl satmama şerhi ve işleme özel uygunluk kontrolleri gerekir. Satın alma tek başına onay garantisi değildir.","#citizenship","Koşulları inceleyin","Resmi rehber · kontrol: 5 Ekim 2026","https://www.invest.gov.tr/tr/investmentguide/sayfalar/acquiring-property-and-citizenship.aspx"],["15,75M","İstanbul nüfusu","2025 yılında İstanbul ili genelinde 15.754.053 kişi yaşıyor. Semt seçerken ulaşım süresini, vapur ve metro bağlantılarını, okulları ve günlük ihtiyaçlara erişimi birlikte değerlendirin.","#districts","Size uygun semti keşfedin","TÜİK · 2025 nüfusu","https://data.tuik.gov.tr/Bulten/Index?p=Adrese-Dayali-Nufus-Kayit-Sistemi-Sonuclari-2025-53899"],["Life Match","Önceliklerinize uygun semt","Sahil yürüyüşleri, yeşil çevre, ailenizin günlük düzeni veya daha kısa ulaşım: önce nasıl yaşamak istediğinizi belirleyin. Bütçeniz ve önceliklerinizle size uygun semtlerin kısa listesini oluşturun.","#districts","Size uygun İstanbul’u bulun"],["Her adımda","Satın alma yolculuğunda rehberlik","İlk sorularınızdan gezilere, belge kontrolünden tapu hazırlığına kadar sıradaki adımı ve sorumlusunu netleştirin. Karar vermeden önce hizmet kapsamını ve gereken uzman desteğini belirleyin.","#guide/remote-checklist","Satın alma sürecini planlayın"]]};
function informationCards(){return `<section class="information-section" id="information" aria-labelledby="information-heading"><div class="wrap"><div class="sectionhead"><div><div class="eyebrow">${lang==='en'?'ISTANBUL, IN PERSPECTIVE':'İSTANBUL’A BİR BAKIŞ'}</div><h2 id="information-heading">${lang==='en'?'A little context. A clearer decision.':'Daha fazla bilgi. Daha net bir karar.'}</h2><p class="subtitle">${lang==='en'?'Understand the essentials, then build your search around what matters to you.':'Temel bilgileri öğrenin; aramanızı sizin için önemli olanlar etrafında şekillendirin.'}</p></div></div><div class="information-grid">${informationData[lang].map((c,i)=>`<article class="information-card ${i===3?'information-dark':''}"><span class="information-number">0${i+1}</span><div class="information-value">${c[0]}</div><h3>${c[1]}</h3><p>${c[2]}</p><a class="information-link" href="${c[3]}">${c[4]} ↗</a>${c[6]?`<a class="information-source" href="${c[6]}" target="_blank" rel="noopener noreferrer">${c[5]} ↗</a>`:''}</article>`).join('')}</div></div></section>`}
const approachCopy={"en":[["shield","A clear buying budget","Separate the price from transaction charges and professional services. Ask for an itemised estimate, the payment currency and who receives each fee."],["people","A mapped-out process","Set out the next steps, required documents and responsibilities. Clarify where legal, tax or other specialist advice is needed before committing."],["video","A useful live viewing","For a remote search, arrange a live viewing of the exact unit when available. Check light, layout and surroundings, then follow up with the relevant documents."],["pin","A neighbourhood that fits","Compare daily life around your priorities: commute, schools, waterfront access and green space. Keep the reasons for each recommendation clear."]],"tr":[["shield","Anlaşılır bir satın alma bütçesi","Satış bedelini işlem giderleri ve profesyonel hizmetlerden ayırın. Kalem kalem döküm, ödeme para birimi ve her ücretin kime ödendiğini isteyin."],["people","Adımları belirlenmiş bir süreç","Sonraki adımları, gereken belgeleri ve sorumluları netleştirin. Karar öncesinde hukuki, vergisel veya başka uzman desteğinin nerede gerektiğini belirleyin."],["video","Faydalı bir canlı gezi","Uzaktan aramada, mümkün olduğunda ilgili daire için canlı görüntülü gezi planlayın. Işık, yerleşim ve çevreyi inceleyin; ardından ilgili belgelerle doğrulayın."],["pin","Yaşamınıza uygun bir semt","Ulaşım, okullar, sahile erişim ve yeşil alanları kendi önceliklerinizle karşılaştırın. Her önerinin nedenini açıkça değerlendirin."]]};
function serviceApproach(){return `<section class="approach-section" id="service-approach"><div class="wrap"><div class="approach-head"><div class="eyebrow">${lang==='en'?'Kayesta Properties · OUR APPROACH':'Kayesta Properties · HİZMET YAKLAŞIMIMIZ'}</div><h2>${lang==='en'?'Clear information.<br>A decision that fits your life.':'Açık bilgiler.<br>Yaşamınıza uygun bir karar.'}</h2><p class="subtitle">${lang==='en'?'Bring the budget, the documents and your everyday priorities into the same conversation.':'Bütçeyi, belgeleri ve günlük yaşam önceliklerinizi birlikte değerlendirin.'}</p></div><div class="approach-grid">${approachCopy[lang].map(x=>`<article class="approach-card"><span class="approach-icon">${uiIcon(x[0])}</span><h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div></div></section>`}
function home(){return `<section class="hero">${heroBackdrop()}<div class="wrap"><div class="eyebrow">ISTANBUL PROPERTY ADVISORY</div><h1>${t('hero')}</h1><p>${t('intro')}</p><form class="search" id="search"><input name="q" aria-label="${lang==='en'?'Project or district':'Proje veya semt'}" placeholder="${lang==='en'?'District, project or keyword…':'Semt, proje veya anahtar kelime…'}"><select name="goal" aria-label="${lang==='en'?'Your goal':'Amacınız'}"><option value="">${lang==='en'?'Any Goal':'Tüm amaçlar'}</option><option value="citizenship">${lang==='en'?'Citizenship':'Vatandaşlık'}</option><option value="residency">${lang==='en'?'Ikamet':'İkamet'}</option><option value="investment">${lang==='en'?'Investment':'Yatırım'}</option><option value="family">${lang==='en'?'Family Home':'Aile evi'}</option></select><select name="budget" aria-label="${lang==='en'?'Your budget':'Bütçeniz'}"><option value="">${lang==='en'?'Any Budget':'Tüm bütçeler'}</option><option value="under-150000">${lang==='en'?'Under $150K':'150 bin USD altı'}</option><option value="150000-300000">${lang==='en'?'$150K–$300K':'150–300 bin USD'}</option><option value="300000-500000">${lang==='en'?'$300K–$500K':'300–500 bin USD'}</option><option value="500000-plus">${lang==='en'?'$500K+':'500 bin USD üzeri'}</option></select><button class="button hero-search-button"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m15.5 15.5 5 5"/></svg><span>${lang==='en'?'Search':'Ara'}</span></button></form><div class="strip hero-highlights"><div><b>${lang==='en'?'Start with your lifestyle':'Yaşam tarzınızdan başlayın'}</b>${lang==='en'?'Explore Istanbul neighbourhoods':'İstanbul semtlerini keşfedin'}</div><div><b>${lang==='en'?'Understand the journey':'Süreci anlayın'}</b>${lang==='en'?'Practical buyer checklists':'Pratik alıcı kontrol listeleri'}</div><div><b>${lang==='en'?'Ask better questions':'Doğru soruları sorun'}</b>${lang==='en'?'A conversation around your goals':'Hedefleriniz üzerine bir görüşme'}</div></div></div></section><section class="wrap section"><div class="sectionhead"><div><div class="eyebrow">LIFE MATCH</div><h2>${t('life')}</h2><p class="subtitle">${t('lifeSub')}</p></div><a class="textlink" href="#districts">${t('viewAll')}</a></div>${lifestyle()}</section><section class="project-collection section"><div class="wrap"><div class="sectionhead"><div><div class="eyebrow">THE COLLECTION</div><h2>${t('featured')}</h2></div><a class="button view-all-projects" href="#projects">${lang==='en'?'View all projects':'Tüm projeleri gör'} →</a></div>${filters()}${empty(true)}</div></section>${informationCards()}${serviceApproach()}<section class="wrap section split"><div><div class="eyebrow">THE BUYING JOURNEY</div><h2>${t('journey')}</h2><p class="subtitle">${lang==='en'?'Take the time to understand location, documents and costs before choosing.':'Seçimden önce konumu, belgeleri ve giderleri anlamaya zaman ayırın.'}</p></div><div class="steps">${(lang==='en'?[['Define your priorities','Budget, preferred neighbourhood, timeframe and purpose.'],['Compare the details','Separate verified documents from estimates and marketing claims.'],['Plan the next step','View the exact unit and clarify responsibilities before committing.']]:[['Önceliklerinizi belirleyin','Bütçe, tercih edilen semt, takvim ve satın alma amacı.'],['Ayrıntıları karşılaştırın','Belgelenmiş bilgileri tahminlerden ve tanıtım iddialarından ayırın.'],['Sonraki adımı planlayın','Karardan önce ilgili daireyi görün ve sorumlulukları netleştirin.']]).map((x,i)=>`<div class="step"><span class="n">0${i+1}</span><div><b>${x[0]}</b><p>${x[1]}</p></div></div>`).join('')}</div></section><section class="faq-section" id="questions"><div class="wrap"><div class="sectionhead"><div><div class="eyebrow">${lang==='en'?'YOUR QUESTIONS, ANSWERED':'SORULARINIZA YANITLAR'}</div><h2>${t('questions')}</h2></div></div>${faq()}</div></section><section class="guide-section" id="buyer-guides"><div class="wrap"><div class="sectionhead"><div><div class="eyebrow">${t('guides')}</div><h2>${t('insights')}</h2></div><a class="textlink" href="#guides">${t('viewAll')}</a></div>${guideCards()}</div></section>${band()}`}
const faqSources={"citizenship":"https://www.invest.gov.tr/en/investmentguide/pages/acquiring-property-and-citizenship.aspx","remote":"https://www.yourkeyturkiye.gov.tr/en/faq","nvi":"https://www.nvi.gov.tr/turk-vatandasliginin-kazanilmasi","process":"https://www.nvi.gov.tr/sss-vatandaslik-hizmetleri","residency":"https://en.goc.gov.tr/residence-permit-types","market":"https://tcmb.gov.tr/wps/wcm/connect/en/tcmb%2Ben/main%2Bmenu/statistics/real%2Bsector%2Bstatistics/residential%2Bproperty%2Bprice%2Bindex"};
const faqQuestions={"en":[["What is the minimum property investment for citizenship?","The real-estate route requires a qualifying property purchase of at least USD 400,000, with a three-year restriction on resale. The exact property and application must meet the official conditions; reaching the price threshold alone does not guarantee citizenship.","citizenship"],["Can I buy without travelling to Istanbul?","Property transactions can be handled through an appropriately authorised representative. Confirm the power of attorney, identity and document requirements with the title-deed office or a qualified professional. A remote purchase does not mean every residency or citizenship step can be completed remotely.","remote"],["How long does the citizenship process take?","The official process includes investment compliance, the relevant residence permit and a citizenship application. We do not promise a completion date. Plan around document preparation and official assessment, and request updates for your specific application.","process"],["Can my spouse and children be included?","The investment-related exceptional route can cover a foreign spouse and minor or dependent foreign children under the applicable rules. Family documents, age and dependency must be assessed individually; inclusion and approval are not automatic.","nvi"],["How is an ikamet permit different from citizenship?","A residence permit authorises a foreign national to stay in Türkiye under its category, duration and conditions. It is not Turkish citizenship. Property ownership can be relevant to a residence application, but does not automatically grant either status.","residency"],["How should I assess an Istanbul property investment?","Compare dated local evidence with the exact unit, title status, building condition, delivery obligations and full ownership costs. Test vacancy, currency and resale assumptions. The central bank’s housing price index is market context, not a forecast or a guarantee for your property.","market"]],"tr":[["Vatandaşlık için asgari gayrimenkul yatırımı ne kadar?","Gayrimenkul yolunda en az 400.000 USD değerinde uygun taşınmaz alımı ve üç yıl satmama şerhi gerekir. Taşınmazın ve başvurunun resmi koşulları sağlaması gerekir; bedel eşiğine ulaşmak tek başına vatandaşlık garantisi değildir.","citizenship"],["İstanbul’a gelmeden satın alabilir miyim?","Taşınmaz işlemleri uygun yetkiler verilmiş bir temsilciyle yürütülebilir. Vekâletname, kimlik ve belge koşullarını tapu müdürlüğü veya yetkin bir uzmanla doğrulayın. Uzaktan alım, ikamet veya vatandaşlığın bütün adımlarının uzaktan tamamlanabileceği anlamına gelmez.","remote"],["Vatandaşlık süreci ne kadar sürer?","Resmi süreç yatırım uygunluğu, ilgili ikamet izni ve vatandaşlık başvurusunu içerir. Kesin bitiş tarihi vaat etmiyoruz. Belge hazırlığı ve resmi değerlendirmeyi dikkate alarak plan yapın; kendi başvurunuzun aşamalarını takip edin.","process"],["Eşim ve çocuklarım da başvuruya dahil olabilir mi?","Yatırımla bağlantılı istisnai yol, ilgili koşullarla yabancı eşi ve ergin olmayan veya bağımlı yabancı çocukları kapsayabilir. Aile belgeleri, yaş ve bağımlılık durumu ayrıca değerlendirilir; dahil edilme ve onay otomatik değildir.","nvi"],["İkamet izni ile vatandaşlık arasındaki fark nedir?","İkamet izni yabancıya türüne, süresine ve koşullarına göre Türkiye’de kalma hakkı verir; Türk vatandaşlığı değildir. Taşınmaz sahipliği ikamet başvurusunda ilgili olabilir, ancak tek başına iki statüden birini otomatik sağlamaz.","residency"],["İstanbul’da emlak yatırımını nasıl değerlendirmeliyim?","Tarihli yerel verileri ilgili daire, tapu durumu, bina koşulları, teslim yükümlülükleri ve toplam giderlerle birlikte değerlendirin. Boş kalma, kur ve yeniden satış varsayımlarını test edin. TCMB konut fiyat endeksi piyasa bağlamı sağlar; daireniz için tahmin veya garanti değildir.","market"]]};
function faq(){return `<div class="faq expanded-faq">${faqQuestions[lang].map((x,i)=>`<details><summary><span class="faq-question">${x[0]}</span></summary><div class="faq-answer"><p>${x[1]}</p><a class="faq-source" href="${faqSources[x[2]]}" target="_blank" rel="noopener noreferrer">${lang==='en'?'Official source':'Resmi kaynak'} ↗</a></div></details>`).join('')}</div><p class="source-note">${lang==='en'?'Sources checked 5 October 2026. Confirm the requirements for your own transaction before making a commitment.':'Kaynak kontrolü: 5 Ekim 2026. Karar vermeden önce kendi işleminizin koşullarını doğrulayın.'}</p>`}
function projects(){const q=new URLSearchParams(location.hash.split('?')[1]).get('q')||'';return pageHead(t('projects'),lang==='en'?'Explore the collection by location and buying goal.':'Koleksiyonu konum ve satın alma amacına göre keşfedin.')+`<section class="wrap section"><form id="search" class="search" style="display:flex;gap:10px;margin-bottom:25px"><input name="q" value="${esc(q)}" placeholder="${lang==='en'?'Search projects or districts':'Proje veya semt ara'}" aria-label="Search"><button class="button">${t('search')}</button></form>${filters()}${q?`<p class="subtitle">${lang==='en'?'Search':'Arama'}: ${esc(q)}</p>`:''}${empty()}</section>`}
function districts(){let n=Number(new URLSearchParams(location.hash.split('?')[1]).get('life'));return pageHead(t('life'),t('lifeSub'))+`<section class="wrap section">${lifestyle()}<div class="notice">${lang==='en'?'These categories are starting points for a conversation, not project availability or a promise about an individual neighbourhood.':'Bu kategoriler görüşme için başlangıç noktalarıdır; proje stok bilgisi veya belirli bir semt hakkında bir vaat değildir.'}</div><h2>${lives[n]?.[lang==='en'?0:1]||t('districts')}</h2><p class="subtitle">${lives[n]?.[2]||'İstanbul'}</p><a class="button" href="#consultation">${t('consult')}</a></section>`}
const services={citizenship:['Citizenship guidance','Vatandaşlık rehberliği'],residency:['Residency guidance','İkamet rehberliği'],remote:['Remote purchase','Uzaktan satın alma'], 'title-deed':['Title deed process','Tapu süreci']};
function citizenshipGuide(){const en=lang==='en';return pageHead(services.citizenship[en?0:1],en?'Key conditions before you choose a property.':'Taşınmaz seçmeden önce temel koşullar.')+`<article class="content"><h2>${en?'USD 400,000 is the starting threshold':'Başlangıç eşiği: 400.000 USD'}</h2><p>${informationData[lang][0][2]}</p><ul><li>${en?'Check the exact property, ownership documents and transaction eligibility before payment.':'Ödeme öncesinde taşınmazı, mülkiyet belgelerini ve işlemin uygunluğunu kontrol edin.'}</li><li>${en?'Confirm valuation, documentation and application steps with a qualified professional.':'Değerleme, belgeler ve başvuru adımlarını yetkin bir uzmanla doğrulayın.'}</li><li>${en?'Budget separately for transaction charges and professional services.':'İşlem giderleri ve profesyonel hizmetler için ayrıca bütçe oluşturun.'}</li></ul><div class="notice">${en?'Approval is subject to the applicable rules and official assessment. Source checked 5 October 2026.':'Onay, ilgili kurallara ve resmi değerlendirmeye bağlıdır. Kaynak kontrolü: 5 Ekim 2026.'}</div><p><a class="textlink" href="${informationData[lang][0][6]}" target="_blank" rel="noopener noreferrer">Invest in Türkiye · ${en?'Official requirements':'Resmi koşullar'} ↗</a></p><a class="button" href="#consultation">${t('consult')}</a></article>`}
function service(route){if(route==='title-deed'){const g=guides.find(x=>x.id==='viewing-checklist');return pageHead(g[lang])+`<article class="content legal-content"><p>${g[lang==='en'?'bodyEn':'bodyTr']}</p><ul>${g[lang==='en'?'listEn':'listTr'].map(x=>`<li>${x}</li>`).join('')}</ul>${legalGuideEnding()}</article>`}if(route==='citizenship')return citizenshipGuide();return pageHead(services[route][lang==='en'?0:1],lang==='en'?'Prepare the right questions before taking the next step.':'Sonraki adımdan önce doğru soruları hazırlayın.')+`<article class="content"><h2>${lang==='en'?'A documented process':'Belgelerle ilerleyen bir süreç'}</h2><p>${lang==='en'?'Your nationality, the exact property, the documents and the current rules can affect the process. We are preparing a dedicated guide for this service.':'Uyruğunuz, ilgili taşınmaz, belgeler ve güncel kurallar süreci etkileyebilir. Bu hizmet için özel rehber hazırlanıyor.'}</p><ul><li>${lang==='en'?'Confirm the property and transaction details.':'Taşınmaz ve işlem ayrıntılarını doğrulayın.'}</li><li>${lang==='en'?'Ask for the required documents and a written cost breakdown.':'Gerekli belgeleri ve yazılı gider dökümünü isteyin.'}</li><li>${lang==='en'?'Clarify who handles each stage and how progress is reported.':'Her aşamayı kimin yöneteceğini ve ilerlemenin nasıl bildirileceğini netleştirin.'}</li></ul><div class="notice">${lang==='en'?'Service-specific legal thresholds and processing times await verification. This draft makes no eligibility or outcome guarantee.':'Hizmete özel yasal eşikler ve işlem süreleri doğrulama bekliyor. Bu taslak uygunluk veya sonuç garantisi vermez.'}</div><a class="button" href="#consultation">${t('consult')}</a></article>`}
function aboutPage(){const en=lang==='en';const copy=en?{
 title:'Find your place in Istanbul. Feel confident about the next step.',intro:'A property search should start with you: the mornings you want, the people you share your home with and the plans you have for the years ahead. Kayesta Properties helps you connect that picture with Istanbul’s neighbourhoods and residential projects, so you can explore with a clearer sense of what matters.',
 eyebrow:'ABOUT KAYESTA PROPERTIES',approach:'Good advice starts with understanding your life',lead:'A beautiful building is only part of the decision. The right surroundings, a workable daily routine and a clear purchase process matter just as much. We bring those questions into the conversation before narrowing your options.',
 principles:[['Your life, your location','Imagine an ordinary weekday in your new home. Would you rather step out towards the waterfront, find a quieter green setting or stay close to the city’s cafés and business districts? We begin with the surroundings you enjoy, then consider family needs, work and everyday convenience alongside the projects.'],['Clear information for your decision','Look beyond the cover image. Layouts, setting, shared spaces and the character of the surrounding neighbourhood all deserve attention. We help structure the comparison and distinguish project information from details that still need confirmation, including current prices, available homes and conditions for foreign buyers.'],['A clear next step','You may be exploring Istanbul for the first time or already preparing a visit. Either way, start with a manageable next step: discuss a location, compare a shortlist or prepare questions for a viewing. Before making a commitment, clarify the documents, costs and professional support your purchase will need.']],
 team:'A personal conversation, with people you can reach',teamIntro:'An international property search can raise questions that a project brochure cannot answer. Meet our Istanbul advisors and our contacts in Canada and Indonesia, and start with the person best placed to understand your next step.',roles:['Property advisor · Your point of contact','Senior property advisor · Istanbul','Property advisor · Turkish, English and Farsi'],bios:['Speak with Ali Kaya about what brings you to Istanbul and what you want from your purchase. He is your point of contact for project enquiries and planning the next step. His Level 5 vocational qualification and university training certificate are available below, so you can review the background behind the conversation.','Mert supports the Istanbul side of your search, helping you explore neighbourhoods, compare projects and prepare useful viewing questions. His focus is on the practical details that connect an attractive property with the way you actually want to live.','Mansoor Eskandari helps buyers discuss their options in Turkish, English and Farsi. From shaping a project shortlist to preparing a viewing, he supports clear communication so you can ask questions comfortably and understand the next stage of your search.'],
 docs:'Qualifications and training',docIntro:'Documents held by Ali Kaya. The copies below have personal identification details concealed.',docNames:['Responsible Real Estate Consultant · Level 5','Real Estate Valuation and Investment Training'],docBodies:['Vocational Qualification Certificate issued by Kariyer Belgelendirme. Issue date: 2 December 2022. The document states an expiry date of 1 December 2027.','Fatih Sultan Mehmet Vakıf University Continuing Education Centre. A 120-hour training programme completed in November 2022.'],open:'View document ↗',verify:'Official document verification ↗',note:'The qualifications shown here belong to Ali Kaya. Select a document to read the copy; personal identification details have been concealed.',
 contact:'What would make Istanbul feel like home?',contactText:'Tell us about the setting you enjoy, the people you are buying for or the question you cannot quite answer yet. You do not need a finished shortlist to begin. A conversation can help you decide what to explore next.',whatsapp:'Speak to Ali on WhatsApp ↗',projects:'Explore the projects →'
 }:{title:'Yaşamınıza uygun bir ev. Anlaşılır bir yol arkadaşlığı.',intro:'Kayesta Properties, İstanbul projelerini, semtleri ve satın alma rehberlerini bir araya getirir. Önce kurmak istediğiniz hayatı konuşur, ardından size uygun projeleri keşfederiz.',eyebrow:'KAYESTA PROPERTIES HAKKINDA',approach:'Proje listesinden önce sizi tanıyalım',lead:'Çevreniz, aileniz, günlük düzeniniz ve satın alma amacınız: arayışınızın başlangıç noktası sizin öncelikleriniz.',principles:[['Yaşamınıza uygun konum','Sahilde yürüyüş, yeşil bir çevre ya da şehrin hareketi… Sizin için neyin önemli olduğunu konuşur, proje seçimini konumla birlikte ele alırız.'],['Kararınız için açık bilgiler','Proje özelliklerini, görselleri ve satın alma sorularını birlikte değerlendirin. Güncel fiyat, stok ve yabancılara satış koşulları ilgili proje için ayrıca teyit edilmelidir.'],['Bir sonraki adım belli olsun','Proje incelemesinden gezi hazırlığına kadar sıradaki adımı ve kimlerle ilerleyeceğinizi öğrenin. Karar vermeden önce profesyonel desteğin kapsamını netleştirin.']],team:'Doğrudan görüşebileceğiniz kişiler',teamIntro:'Ali Kaya ve danışmanlık ekibiyle görüşmenize buradan başlayabilirsiniz.',roles:['Gayrimenkul danışmanı · İletişim kişiniz','Kıdemli gayrimenkul danışmanı · İstanbul','Gayrimenkul danışmanı · Türkçe, İngilizce ve Farsça'],bios:['Ali Kaya, İstanbul’daki proje arayışınız ve sonraki adımlar için iletişim kişinizdir. Mesleki yeterlilik belgesini ve eğitim sertifikasını aşağıda inceleyebilirsiniz.','Mert, İstanbul semtlerini ve projelerini tanımanız, gezi hazırlığı ve satın almanın pratik adımlarını anlamanız için destek verir.','Mansoor Eskandari, proje seçimi, geziler ve satın alma sorularında Türkçe, İngilizce ve Farsça iletişimle alıcılara destek verir.'],docs:'Mesleki yeterlilik ve eğitim',docIntro:'Ali Kaya adına düzenlenen belgeler. Aşağıdaki kopyalarda kişisel kimlik bilgileri kapatılmıştır.',docNames:['Sorumlu Emlak Danışmanı · Seviye 5','Gayrimenkul Değerlendirme ve Yatırımı Uzmanlığı'],docBodies:['Kariyer Belgelendirme tarafından düzenlenen Mesleki Yeterlilik Belgesi. Düzenlenme: 2 Aralık 2022. Belgede belirtilen geçerlilik sonu: 1 Aralık 2027.','Fatih Sultan Mehmet Vakıf Üniversitesi Sürekli Eğitim Merkezi. Kasım 2022’de tamamlanan 120 saatlik eğitim programı.'],open:'Belgeyi incele ↗',verify:'Resmî belge doğrulama ↗',note:'Bunlar Ali Kaya’nın kişisel mesleki yeterlilik ve eğitim belgeleridir. Ayrı bir şirket yetki belgesi veya satın alma sonucu garantisi olarak sunulmaz.',contact:'İstanbul’daki hayatınızı konuşalım',contactText:'Nasıl bir yer aradığınızı anlatın. Önce sevdiğiniz çevreden ve aklınızdaki sorulardan başlayabiliriz.',whatsapp:'Ali ile WhatsApp üzerinden görüşün ↗',projects:'Projeleri keşfedin →'};
 return `<div class="about-page"><section class="about-intro"><div class="wrap"><div class="eyebrow">${copy.eyebrow}</div><h1>${copy.title}</h1><p>${copy.intro}</p><a class="button" href="#projects">${copy.projects}</a></div></section><section class="wrap section about-method"><div class="eyebrow">${en?'OUR APPROACH':'YAKLAŞIMIMIZ'}</div><h2>${copy.approach}</h2><p class="subtitle">${copy.lead}</p><div class="about-principles">${copy.principles.map((x,i)=>`<article><span class="about-step">0${i+1}</span><h3>${x[0]}</h3><p>${x[1]}</p></article>`).join('')}</div></section><section class="about-journey"><div class="wrap"><div class="eyebrow">FROM FIRST QUESTION TO A CLEARER PLAN</div><h2>A search that moves at your pace</h2><div class="about-journey-grid"><article><span>01</span><h3>Tell us what matters</h3><p>Start with your preferred surroundings, your household and your reason for buying. Share a budget when you are ready, or bring it into the conversation straight away.</p></article><article><span>02</span><h3>Explore a focused selection</h3><p>Compare projects in context. Consider the neighbourhood, home layouts and everyday setting, rather than choosing on a photograph alone.</p></article><article><span>03</span><h3>Ask the important questions</h3><p>Before a decision, confirm the current offer, the exact home and foreign-buyer sales conditions. Bring document and cost questions into the discussion early.</p></article><article><span>04</span><h3>Plan your next step</h3><p>Decide whether to explore another area, prepare a viewing or discuss the purchase process. Clarify responsibilities and the agreed support before moving forward.</p></article></div></div></section><section class="about-team section"><div class="wrap"><div class="eyebrow">${en?'MEET THE TEAM':'EKİBİ TANIYIN'}</div><h2>${copy.team}</h2><p class="subtitle">${copy.teamIntro}</p><div class="about-team-grid">${['Ali Kaya','Mert','Mansoor Eskandari','Sam Khadem Azerian','Aref Insondoyo'].map((name,i)=>`<article class="about-person"><div class="about-portrait"><img class="${i===1?'portrait-mert':'portrait-standard'}" src="assets/team/${['ali-kaya','mert','mansoor','sam','aref'][i]}-corporate-tie-v2.webp" alt="${name} — Kayesta Properties" loading="lazy"></div><h3>${name}</h3><div class="about-role">${i===3?'Canada representative · Ontario':i===4?'Indonesia representative · Bali & Java':copy.roles[i]}</div><p>${i===3?'Sam Khadem Azerian is the contact for Ontario, including Toronto and the Greater Toronto Area. He helps buyers discuss their priorities, explore local property options and prepare the questions they need to ask before taking the next step.':i===4?'Aref Insondoyo is the contact for Indonesia, with coverage across Bali, Jakarta, Yogyakarta and Java. He helps buyers explore the local setting, discuss property options and identify the practical questions that need local professional attention.':copy.bios[i]}</p>${i===0?`<a href="tel:${SITE.contact.tel}">${SITE.contact.phone}</a>`:i===3?`<a href="tel:+14169105910">Call Sam ↗</a>`:i===4?`<a href="https://wa.me/62895422373683" target="_blank" rel="noopener noreferrer">Message Aref ↗</a>`:''}</article>`).join('')}</div></div></section><section class="wrap section about-documents"><div class="eyebrow">${en?'DOCUMENTS':'BELGELER'}</div><h2>${copy.docs}</h2><p class="subtitle">${copy.docIntro}</p><div class="about-doc-grid">${['ali-kaya-myk','ali-kaya-fsmvu'].map((file,i)=>`<article><a class="about-doc-preview" href="assets/credentials/${file}.pdf" target="_blank" rel="noopener noreferrer" aria-label="${copy.open}: ${copy.docNames[i]}"><img src="assets/credentials/${file}.jpg" alt="${copy.docNames[i]} — Ali Kaya" loading="lazy"></a><div class="about-doc-body"><h3>${copy.docNames[i]}</h3><p>${copy.docBodies[i]}</p><a class="textlink" href="assets/credentials/${file}.pdf" target="_blank" rel="noopener noreferrer">${copy.open}</a></div></article>`).join('')}</div><p class="about-doc-note">${copy.note}</p><a class="textlink" href="https://www.turkiye.gov.tr/belge-dogrulama" target="_blank" rel="noopener noreferrer">${copy.verify}</a></section><section class="about-contact"><div class="wrap"><h2>${copy.contact}</h2><p>${copy.contactText}</p><a class="button" href="https://wa.me/905325529279" target="_blank" rel="noopener noreferrer">${copy.whatsapp}</a></div></section></div>`}

function contactDetails(){return `<div class="contact-details"><a class="contact-phone" href="tel:${SITE.contact.tel}">${SITE.contact.phone}</a><address>${esc(SITE.contact.address)}</address></div>`}


function legalGuideEnding(){const en=lang==='en';const related=[['guide/viewing-checklist',en?'ENGLISH GUIDE':'İNGİLİZCE REHBER',en?'Title deed review guide':'Tapu inceleme rehberi (English)','en'],['citizenship',en?'CITIZENSHIP':'VATANDAŞLIK',en?'Citizenship by property investment':'Gayrimenkul yatırımıyla vatandaşlık'],['residency',en?'RESIDENCY':'İKAMET',en?'Residence permit guide':'İkamet izni rehberi'],['guide/remote-checklist',en?'REMOTE PURCHASE':'UZAKTAN ALIM',en?'Planning a purchase from abroad':'Yurt dışından satın alma hazırlığı'],['projects',en?'PROJECTS':'PROJELER',en?'Istanbul project collection':'İstanbul proje koleksiyonu'],['districts',en?'DISTRICTS':'SEMTLER',en?'Find your Istanbul neighbourhood':'Size uygun İstanbul semtini bulun']];return `<section class="legal-review"><div class="eyebrow">${en?'OUR VIEW':'DEĞERLENDİRMEMİZ'}</div><h2>${en?'Prepare before the signature':'İmzadan önce hazırlanın'}</h2><p>${en?'Treat the title-deed appointment as one step in a documented purchase. Review the exact unit and title record, organise the required documents and agree a written payment sequence before committing. Confirm the application and appointment requirements with the land registry; if using WebTapu, clarify who is authorised to submit the application.':'Tapu randevusunu, belgelerle ilerleyen satın almanın bir aşaması olarak değerlendirin. Karar vermeden önce ilgili daireyi ve tapu kaydını inceleyin, gerekli belgeleri hazırlayın ve ödeme sırasını yazılı olarak netleştirin. Başvuru ve randevu koşullarını tapu müdürlüğüyle doğrulayın; WebTapu kullanılacaksa başvuruyu kimin hangi yetkiyle yapacağını belirleyin.'}</p><p>${en?'Declare the actual transfer price. The Revenue Administration explains that title-deed charges use this value, with the property tax value as the minimum assessment basis. Ask for a transaction-specific cost breakdown and keep payment records.':'Gerçek devir bedelini beyan edin. Gelir İdaresi, tapu harcının bu bedel üzerinden hesaplandığını ve emlak vergisi değerinin alt sınır olduğunu açıklar. Kendi işleminize özel gider dökümü isteyin ve ödeme belgelerini saklayın.'}</p><a class="legal-source" href="https://cdn.gib.gov.tr/api/gibportal-file/file/getFileResources?objectKey=arsiv%2Fyardim-kaynaklar%2Finfografikler%2Fpdfs%2Ftapuharci.pdf" target="_blank" rel="noopener noreferrer">${en?'Revenue Administration · Title-deed charges':'Gelir İdaresi · Tapu harcı'} ↗</a><div class="legal-signature">Ali Kaya</div></section><section class="legal-cta"><h2>${en?'Plan your title-deed questions with us':'Tapu sorularınızı birlikte planlayalım'}</h2><p>${en?'Tell us the property and the stage you have reached. We can start by clarifying your document checklist, the questions for your representative and the next steps to verify.':'Taşınmazı ve bulunduğunuz aşamayı paylaşın. Belge kontrol listenizi, temsilcinize soracağınız soruları ve doğrulanacak sonraki adımları birlikte netleştirerek başlayabiliriz.'}</p><a class="button" href="https://wa.me/905325529279" target="_blank" rel="noopener noreferrer">${en?'Start on WhatsApp':'WhatsApp’tan başlayın'} →</a></section><section class="legal-related"><h2>${en?'Related guides':'İlgili rehberler'}</h2><div class="related-grid">${related.map(x=>`<a class="related-card" href="#${x[0]}" ${x[3]?'data-guide-language="'+x[3]+'"':''}><span class="related-category">${x[1]}</span><strong>${x[2]}</strong><span aria-hidden="true">→</span></a>`).join('')}</div></section>`}

function siteFooter(){const en=lang==='en';const links=[['projects',en?'Projects':'Projeler'],['districts',en?'Districts & Life Match':'Semtler ve yaşam eşleştirme'],['citizenship',en?'Citizenship guidance':'Vatandaşlık rehberliği'],['residency',en?'Residence permits':'İkamet izinleri'],['guides',en?'Buyer guides':'Alıcı rehberleri'],['knowledge',en?'Knowledge base':'Bilgi merkezi'],['about',en?'About us':'Hakkımızda'],['consultation',en?'Consultation':'Danışmanlık']];return `<div class="wrap footer-main"><div class="footer-intro"><a class="footerbrand" href="#home">${esc(SITE.name)}</a><div class="footer-tagline">${en?'ISTANBUL PROPERTY ADVISORY':'İSTANBUL GAYRİMENKUL DANIŞMANLIĞI'}</div><p>${en?'Explore Istanbul with clear information about neighbourhoods, property documents and the buying process. Start with your priorities and plan your next step.':'İstanbul’u semtler, taşınmaz belgeleri ve satın alma süreci hakkında açık bilgilerle keşfedin. Önceliklerinizden başlayın ve sonraki adımınızı planlayın.'}</p><a class="footer-social" href="https://wa.me/905325529279" target="_blank" rel="noopener noreferrer" aria-label="WhatsApp">↗</a></div><div class="footer-explore"><h4>${en?'EXPLORE':'KEŞFEDİN'}</h4><nav class="footer-links" aria-label="${en?'Footer navigation':'Alt menü'}">${links.map(x=>`<a href="#${x[0]}">${x[1]}</a>`).join('')}</nav></div></div><div class="wrap footer-contact-row"><div><h4>${en?'TALK TO ALİ':'ALİ İLE GÖRÜŞÜN'}</h4><div id="footer-contact">${contactDetails()}</div></div><a class="button footer-whatsapp" href="https://wa.me/905325529279" target="_blank" rel="noopener noreferrer">${en?'Start on WhatsApp':'WhatsApp’tan başlayın'} →</a></div><div class="wrap footbase"><span>© 2026 ${esc(SITE.name)}</span><div><a href="#privacy">${en?'Privacy':'Gizlilik'}</a><a href="#terms">${en?'Terms':'Koşullar'}</a></div></div>`}

function consultation(){return pageHead(lang==='en'?'Start a conversation':'Bir görüşmeyle başlayın',t('talkSub'))+`<div class="content"><section class="consult-contact"><h2>${t('contact')}</h2>${contactDetails()}</section><div class="notice">${lang==='en'?'Draft form: online delivery is not connected. You can download your request; it will not be sent or stored in Supabase.':'Taslak form: çevrimiçi gönderim bağlı değil. Talebinizi indirebilirsiniz; gönderilmeyecek veya Supabase’e kaydedilmeyecek.'}</div><form id="consultform"><div class="formgrid"><div class="field"><label for="name">${lang==='en'?'Name':'Ad'}</label><input id="name" name="name" required autocomplete="name"></div><div class="field"><label for="email">Email</label><input id="email" name="email" type="email" required autocomplete="email"></div><div class="field"><label for="country">${lang==='en'?'Country of residence':'Yaşadığınız ülke'}</label><input id="country" name="country" autocomplete="country-name"></div><div class="field"><label for="preferred">${lang==='en'?'Preferred language':'Tercih edilen dil'}</label><select name="preferred" id="preferred"><option>English</option><option>Türkçe</option><option>اردو</option><option>فارسی</option><option>العربية</option><option>Bahasa Indonesia</option></select></div><div class="field"><label for="budget">${lang==='en'?'Budget range':'Bütçe aralığı'}</label><select id="budget" name="budget"><option value="" selected>${lang==='en'?'Select your budget':'Bütçenizi seçin'}</option><option value="USD 200,000–400,000">${lang==='en'?'USD 200,000–400,000':'200.000–400.000 USD'}</option><option value="Above USD 400,000">${lang==='en'?'Above USD 400,000':'400.000 USD üzeri'}</option></select></div><div class="field"><label for="goal">${lang==='en'?'Buying goal':'Satın alma amacı'}</label><select id="goal" name="goal"><option>${lang==='en'?'A home to live in':'Yaşamak için ev'}</option><option>${lang==='en'?'Investment':'Yatırım'}</option><option>${lang==='en'?'Still exploring':'Araştırıyorum'}</option></select></div><div class="field full"><label for="message">${lang==='en'?'What matters to you?':'Sizin için neler önemli?'}</label><textarea id="message" name="message"></textarea></div></div><div class="formActions"><button class="button">${lang==='en'?'Download request draft':'Talep taslağını indir'}</button><span class="subtitle" id="formstatus" role="status"></span></div></form></div>`}
function calculator(){return pageHead(lang==='en'?'Rental yield calculator':'Kira getirisi hesaplayıcı',lang==='en'?'Calculate a simple scenario using your own figures.':'Kendi rakamlarınızla basit bir senaryo hesaplayın.')+`<div class="content"><form id="calc"><div class="formgrid">${[['price',lang==='en'?'Purchase price':'Satın alma bedeli',200000],['costs',lang==='en'?'One-time buying costs':'Tek seferlik alım giderleri',10000],['rent',lang==='en'?'Monthly rent':'Aylık kira',1000],['expenses',lang==='en'?'Annual operating costs':'Yıllık işletme giderleri',2500],['vacancy',lang==='en'?'Vacant months per year':'Yılda boş kalan ay',1]].map(([id,label,value])=>`<div class="field"><label for="${id}">${label}</label><input type="number" id="${id}" name="${id}" min="0" ${id==='vacancy'?'max="12"':'step="any"'} value="${value}" required></div>`).join('')}<div class="field"><label for="currency">${lang==='en'?'Currency (same for all figures)':'Para birimi (tüm rakamlar için aynı)'}</label><select id="currency" name="currency"><option>USD</option><option>TRY</option><option>EUR</option><option>GBP</option><option>CAD</option><option>AED</option></select></div></div><div class="formActions"><button class="button">${lang==='en'?'Calculate':'Hesapla'}</button></div></form><div class="result" id="calcresult" aria-live="polite"></div><div class="notice">${lang==='en'?'Illustrative calculation from your inputs. No market forecast or guaranteed return. Financing, tax, appreciation and exchange-rate changes are not included.':'Girdiğiniz rakamlarla temsili hesaplama. Piyasa tahmini veya getiri garantisi değildir. Finansman, vergi, değer artışı ve döviz değişimi dahil değildir.'}</div></div>`}
// Remember each route's reading position for this browser tab.
const PagePosition = (() => {
 const key=()=>location.hash||'#home';
 let positions={};
 try{positions=JSON.parse(sessionStorage.getItem('kayesta-page-positions')||'{}')||{};}catch{}
 let active=key(),rendered=false,leaving=false,restoring=false,generation=0;
 if('scrollRestoration' in history)history.scrollRestoration='manual';
 function save(){if(!rendered||leaving||restoring)return;positions[active]=Math.max(0,window.scrollY);try{sessionStorage.setItem('kayesta-page-positions',JSON.stringify(positions));}catch{}}
 window.addEventListener('scroll',save,{passive:true});
 window.addEventListener('pagehide',save);
 document.addEventListener('click',event=>{
  const a=event.target.closest?.('a[href]');
  if(!a||event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey||a.target==='_blank'||a.hasAttribute('download'))return;
  const url=new URL(a.href,location.href);
  if(url.origin===location.origin&&(url.pathname!==location.pathname||url.hash!==location.hash)){save();leaving=true;}
 },true);
 window.addEventListener('popstate',()=>{save();leaving=true;});
 return {enter(){
  const next=key(),changed=!rendered||next!==active;
  active=next;rendered=true;leaving=false;
  if(!changed)return undefined;
  restoring=true;
  return Number.isFinite(positions[next])?positions[next]:null;
 },restore(y){
  if(y===undefined)return;
  const token=++generation;
  const move=()=>window.scrollTo({top:y||0,left:0,behavior:'instant'});
  move();
  requestAnimationFrame(()=>{if(token!==generation)return;move();requestAnimationFrame(()=>{if(token!==generation)return;move();restoring=false;});});
 }};
})();
function render(){const readingPosition=PagePosition.enter();let route=location.hash.slice(1).split('?')[0]||'home';document.documentElement.lang=lang;const brandLabel=document.getElementById('brand');if(brandLabel)brandLabel.textContent=SITE.name;document.querySelectorAll('[data-t]').forEach(e=>e.textContent=t(e.dataset.t));let html='';const enhanced=ProjectExplorer.page(route)??KayestaPages.page(route);if(enhanced!==null)html=enhanced;else if(route==='home')html=home();else if(route==='projects')html=projects();else if(route==='project-template')html=projectTemplate();else if(route==='districts')html=districts();else if(route==='guides'||route==='knowledge')html=pageHead(route==='guides'?t('guides'):(lang==='en'?'Knowledge base':'Bilgi merkezi'))+`<section class="wrap section">${guideCards()}<div style="margin-top:40px">${faq()}</div></section>`;else if(route.startsWith('guide/')){let g=guides.find(g=>g.id===route.slice(6));html=g?pageHead(g[lang])+`<article class="content"><p>${g[lang==='en'?'bodyEn':'bodyTr']}</p><ul>${g[lang==='en'?'listEn':'listTr'].map(x=>`<li>${x}</li>`).join('')}</ul>${g.id==='viewing-checklist'?legalGuideEnding():''}${g.source?`<p class="source-note">${lang==='en'?'Source checked 5 October 2026':'Kaynak kontrolü: 5 Ekim 2026'} · <a href="${g.source}" target="_blank" rel="noopener noreferrer">${lang==='en'?'Official reference':'Resmi kaynak'} ↗</a></p>`:''}<a class="button" href="#consultation">${t('consult')}</a></article>`:pageHead('Page not found')}else if(services[route])html=service(route);else if(route==='calculator')html=calculator();else if(route==='consultation')html=consultation();else if(['canada','indonesia'].includes(route))html=pageHead((route==='canada'?'Canada':'Indonesia')+(lang==='en'?' Buyers':' Alıcıları'))+`<article class="content"><h2>${lang==='en'?'Plan your Istanbul search from abroad':'İstanbul aramanızı yurt dışından planlayın'}</h2><p>${lang==='en'?'Start with a shortlist, a budget in a clearly stated currency, and a realistic viewing plan. Preferred language and time zone can be included in your consultation request.':'Kısa liste, para birimi belirtilmiş bütçe ve gerçekçi gezi planıyla başlayın. Görüşme talebinize tercih edilen dili ve saat dilimini ekleyebilirsiniz.'}</p><div class="notice">${lang==='en'?'Local office addresses and contact details await confirmation.':'Yerel ofis adresleri ve iletişim bilgileri teyit bekliyor.'}</div><a class="button" href="#consultation">${t('consult')}</a></article>`;else if(route==='about')html=aboutPage();else if(['privacy','terms'].includes(route))html=pageHead(route==='privacy'?(lang==='en'?'Privacy':'Gizlilik'):(lang==='en'?'Terms':'Koşullar'))+`<article class="content"><div class="notice">${lang==='en'?'Draft — final policy awaits the operating company and data-processing details.':'Taslak — nihai politika işletme ve veri işleme ayrıntılarını bekliyor.'}</div><p>${lang==='en'?'This design draft has no online lead submission. Consultation drafts are downloaded on your own device. Your language preference is stored in this browser. The Google Fonts service is requested for typography.':'Bu tasarım taslağında çevrimiçi talep gönderimi yoktur. Talep taslakları kendi cihazınıza indirilir. Dil tercihiniz bu tarayıcıda saklanır. Yazı tipi için Google Fonts hizmetine istek yapılır.'}</p></article>`;else html=pageHead(lang==='en'?'Page not found':'Sayfa bulunamadı')+`<div class="content"><a class="button" href="#home">Home</a></div>`;document.getElementById('app').classList.toggle('all-projects-page',route==='projects');document.getElementById('app').innerHTML=html;ProjectExplorer.bind();const pageTitle=document.querySelector('#app h1')?.textContent?.trim();document.title=pageTitle?`${pageTitle} · ${SITE.name}`:SITE.name;document.getElementById('site-footer').innerHTML=siteFooter();document.getElementById('contact-shortcuts').innerHTML=`<a class="floating-whatsapp" href="https://wa.me/905325529279" target="_blank" rel="noopener noreferrer" aria-label="WhatsApp"><svg viewBox="0 0 32 32" aria-hidden="true"><path d="M26.6 5.4a14 14 0 0 0-22 16.8L2.5 29.5l7.5-2a14 14 0 0 0 16.6-22.1Z" fill="none" stroke="currentColor" stroke-width="2.1"/><path d="M11 9.5c-.8-.3-1.7.5-2 1.3-.8 2 1.1 5.5 3.3 7.7 2.4 2.4 6 4.2 8 3.3 1-.4 2-1.9 1.7-2.7-.2-.5-3.1-1.9-3.6-1.7-.4.2-1.2 1.5-1.6 1.5-.9.1-4.2-2.6-4.4-3.6-.1-.4 1.2-1.2 1.3-1.7.2-.5-1.9-3.9-2.7-4.1Z" fill="currentColor"/></svg></a>`;document.getElementById('mainNav').classList.remove('open');document.querySelector('.mobile').setAttribute('aria-expanded','false');document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.remove('active');x.setAttribute('aria-pressed','false')});b.classList.add('active');b.setAttribute('aria-pressed','true')});const search=document.getElementById('search');if(search)search.onsubmit=e=>{e.preventDefault();const query=new URLSearchParams();for(const [key,value] of new FormData(search)){if(value)query.set(key,value)}location.hash='projects?'+query.toString()};const c=document.getElementById('calc');if(c){c.onsubmit=e=>{e.preventDefault();calculate()};calculate()}const f=document.getElementById('consultform');if(f)KayestaPages.bindConsultation(f);PagePosition.restore(readingPosition);if(readingPosition===null&&route==='knowledge'){const topic=new URLSearchParams(location.hash.split('?')[1]).get('topic');if(/^[0-3]$/.test(topic||''))requestAnimationFrame(()=>requestAnimationFrame(()=>document.getElementById('knowledge-topic-'+topic)?.scrollIntoView({block:'start'})));}}
function calculate(){let f=new FormData(document.getElementById('calc'));let price=+f.get('price'),costs=+f.get('costs'),rent=+f.get('rent'),expenses=+f.get('expenses'),vacancy=+f.get('vacancy');let income=rent*(12-vacancy),total=price+costs;let r=document.getElementById('calcresult');if(total<=0||[price,costs,rent,expenses,vacancy].some(v=>!Number.isFinite(v)||v<0)||vacancy>12){r.textContent=lang==='en'?'Enter valid figures and a positive total cost.':'Geçerli rakamlar ve sıfırdan büyük toplam gider girin.';return}r.innerHTML=`<span>${lang==='en'?'Net yield on total buying cost':'Toplam alım giderine göre net getiri'}</span><br><strong>${((income-expenses)/total*100).toFixed(2)}%</strong><p>${lang==='en'?'Annual income after stated operating costs':'Belirtilen işletme giderleri sonrası yıllık gelir'}: ${(income-expenses).toLocaleString(lang==='en'?'en-US':'tr-TR')} ${esc(f.get('currency'))}</p>`}
document.querySelector('.mobile').onclick=e=>{const open=document.getElementById('mainNav').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',open)};window.addEventListener('hashchange',render);render();

function projectTemplate(){const labels=lang==='en'?['Location','Property type','Unit types','Gross / net area','Price and currency','Payment plan','Project status','Last verification','Source documents']:['Konum','Taşınmaz türü','Daire tipleri','Brüt / net alan','Fiyat ve para birimi','Ödeme planı','Proje durumu','Son doğrulama','Kaynak belgeler'];return pageHead(lang==='en'?'Project detail template':'Proje detay şablonu',lang==='en'?'An empty layout ready for an individually approved project.':'Tek tek onaylanmış proje için hazırlanmış boş sayfa düzeni.')+`<section class="wrap section"><div class="detail-grid"><div><div class="placeholder-image large"><span>＋</span><small>${lang==='en'?'Cover image — empty':'Kapak görseli — boş'}</small></div><div class="gallery-placeholders">${[1,2,3].map(i=>`<div class="placeholder-image"><small>${lang==='en'?'Image slot':'Görsel alanı'} ${i}</small></div>`).join('')}</div></div><div class="detail-facts"><div class="eyebrow">${lang==='en'?'PROJECT INFORMATION':'PROJE BİLGİLERİ'}</div>${labels.map(l=>`<div><span>${l}</span><b>—</b></div>`).join('')}</div></div><div class="notice">${lang==='en'?'No real project data or images have been added. Each project will be reviewed with you before it is placed here.':'Gerçek proje bilgisi veya görseli eklenmedi. Her proje buraya yerleştirilmeden önce sizinle incelenecek.'}</div><div class="cards">${(lang==='en'?['Delivery & occupancy','Facilities','Sales contact']:['Teslim ve yaşam durumu','Sosyal olanaklar','Satış irtibatı']).map(l=>`<div class="card"><h3>${l}</h3><p>—</p></div>`).join('')}</div></section>`}

function heroBackdrop(){if(!SITE.heroPhoto)return '';return `<div class="hero-photo" aria-hidden="true"><img src="${esc(SITE.heroPhoto)}" alt="" fetchpriority="high" decoding="async"></div><div class="photo-shade" aria-hidden="true"></div>`}
